// Calculate aging for each pending invoice and categorize into reminder tiers
const items = $input.all();
const results = [];
const now = Date.now();

for (const item of items) {
  const rows = item.json.data || [];

  for (const row of rows) {
    // Parse received_at timestamp
    const receivedAt = row.received_at || row.created_at || '';
    let ageHours = 0;

    if (receivedAt) {
      const receivedTime = new Date(receivedAt).getTime();
      if (!isNaN(receivedTime)) {
        ageHours = (now - receivedTime) / (1000 * 60 * 60);
      }
    }

    // Current reminder count (default 0)
    const reminderCount = parseInt(row.reminder_count || '0', 10);

    // Determine reminder tier
    // Tier 0: no reminder yet, age 1-3 hours
    // Tier 1: first reminder sent, age 4-11 hours
    // Tier 2: second reminder sent, age 12-24 hours
    // Tier 3: escalation, age > 24 hours
    let tier = 'none';
    let shouldRemind = false;
    let messageText = '';
    let recipient = 'owner';

    if (ageHours > 24) {
      // Escalation: notify admin
      tier = 'escalation';
      shouldRemind = reminderCount < 4; // max 1 escalation
      recipient = 'admin';
      messageText =
        '⚠️ <b>ESCALATION: Invoice belum di-approve > 24 jam</b>\n\n' +
        '🏢 Vendor: ' + (row.vendor || '-') + '\n' +
        '🔢 No. Invoice: ' + (row.invoice_number || '-') + '\n' +
        '💰 Nominal: Rp ' + (Number(row.amount) || 0).toLocaleString('id-ID') + '\n' +
        '📅 Diterima: ' + receivedAt.substring(0, 16) + '\n' +
        '⏰ Usia: ' + Math.round(ageHours) + ' jam\n' +
        '📊 Reminder dikirim: ' + reminderCount + 'x\n\n' +
        '💡 Owner belum merespon. Mohon follow up langsung.';
    } else if (ageHours > 12 && reminderCount < 3) {
      // Tier 3: reminder ke-3
      tier = 'tier3';
      shouldRemind = true;
      messageText =
        '🔔 <b>Reminder #3: Invoice menunggu approval</b>\n\n' +
        '🏢 Vendor: ' + (row.vendor || '-') + '\n' +
        '🔢 No. Invoice: ' + (row.invoice_number || '-') + '\n' +
        '💰 Nominal: Rp ' + (Number(row.amount) || 0).toLocaleString('id-ID') + '\n' +
        '⏰ Sudah ' + Math.round(ageHours) + ' jam menunggu.\n\n' +
        'Mohon segera approve atau reject.';
    } else if (ageHours > 4 && reminderCount < 2) {
      // Tier 2: reminder ke-2
      tier = 'tier2';
      shouldRemind = true;
      messageText =
        '🔔 <b>Reminder #2: Invoice menunggu approval</b>\n\n' +
        '🏢 Vendor: ' + (row.vendor || '-') + '\n' +
        '🔢 No. Invoice: ' + (row.invoice_number || '-') + '\n' +
        '💰 Nominal: Rp ' + (Number(row.amount) || 0).toLocaleString('id-ID') + '\n' +
        '⏰ Sudah ' + Math.round(ageHours) + ' jam menunggu.\n\n' +
        'Jangan lupa approve ya.';
    } else if (ageHours > 1 && reminderCount < 1) {
      // Tier 1: reminder ke-1
      tier = 'tier1';
      shouldRemind = true;
      messageText =
        '🔔 <b>Reminder: Ada invoice baru menunggu approval</b>\n\n' +
        '🏢 Vendor: ' + (row.vendor || '-') + '\n' +
        '🔢 No. Invoice: ' + (row.invoice_number || '-') + '\n' +
        '💰 Nominal: Rp ' + (Number(row.amount) || 0).toLocaleString('id-ID') + '\n' +
        '⏰ Sudah ' + Math.round(ageHours) + ' jam menunggu.\n\n' +
        'Silakan approve atau reject.';
    }

    if (shouldRemind && messageText) {
      results.push({
        json: {
          tier: tier,
          recipient: recipient,
          message: messageText,
          invoice_id: row.invoice_id || '',
          vendor: row.vendor || '',
          invoice_number: row.invoice_number || '',
          amount: row.amount || 0,
          age_hours: Math.round(ageHours),
          reminder_count: reminderCount + 1,
          last_reminder_at: new Date().toISOString(),
          chat_id: recipient === 'admin'
            ? ($env.TELEGRAM_ADMIN_CHAT_ID || '')
            : ($env.TELEGRAM_OWNER_CHAT_ID || '')
        }
      });
    }
  }
}

console.log('[REMINDER] Processed ' + items.length + ' batches, found ' + results.length + ' invoices to remind');

return results.length > 0 ? results : [{ json: { tier: 'none', message: 'No invoices need reminders' } }];

// Route reminders by tier: tier1/tier2/tier3 → owner, escalation → admin
const items = $input.all();
const tier1 = [];
const tier2 = [];
const tier3 = [];
const escalation = [];

for (const item of items) {
  const tier = item.json.tier;
  if (tier === 'tier1') tier1.push(item);
  else if (tier === 'tier2') tier2.push(item);
  else if (tier === 'tier3') tier3.push(item);
  else if (tier === 'escalation') escalation.push(item);
}

// Return all tiers in order (n8n will split by output index)
const allItems = [...tier1, ...tier2, ...tier3, ...escalation];

console.log('[ROUTE] tier1=' + tier1.length + ' tier2=' + tier2.length + ' tier3=' + tier3.length + ' escalation=' + escalation.length);

// Return with tier tag for downstream routing
return allItems.length > 0 ? allItems : [{ json: { tier: 'none', message: 'No reminders to send' } }];

// Filter: only tier1, tier2, tier3 items (owner reminders)
return $input.all().filter(item =>
  item.json.tier === 'tier1' ||
  item.json.tier === 'tier2' ||
  item.json.tier === 'tier3'
);

